def plan2(st, blocked, maxd=8):
    import collections
    PR=(18,57); ORR=(51,40)
    n=len(st)
    def goal(s):
        return (any(s[i][0]==PR and s[i][1]=='p' for i in range(1,n))
                and any(s[i][0]==ORR and s[i][1]=='O' for i in range(1,n)))
    if goal(st): return []
    seen={st:None}; q=collections.deque([st]); found=None
    for d in range(maxd):
        stop=False
        for _ in range(len(q)):
            s=q.popleft()
            for i in range(1,n):
                l=list(s); l[0],l[i]=l[i],l[0]; l=tuple(l)
                if l not in seen and state_ok(l,blocked):
                    seen[l]=(s,('swap',i))
                    if goal(l): found=l; stop=True; break
                    q.append(l)
                elif l not in seen:
                    seen[l]=(s,('swap',i))  # mark invalid-but-seen to avoid recompute
                if stop: break
            if stop: break
            for (r,c) in CAND:
                if any(s[j][0]==(r,c) for j in range(n)): continue
                l=list(s); l[0]=((r,c),s[0][1]); l=tuple(l)
                if l in seen: continue
                if not state_ok(l,blocked):
                    seen[l]=(s,None); continue
                seen[l]=(s,('tp',(r,c)))
                if goal(l): found=l; stop=True; break
                q.append(l)
            if stop: break
        if stop: break
    if found is None: return None
    chain=[]; s=found
    while seen[s] is not None:
        prev,mv=seen[s]
        if mv is not None: chain.append(mv)
        s=prev
    chain.reverse(); return chain
