def full2(fr):
    seg=fr.segmentation; dm=[]
    for n in seg['nodes']:
        b=n['boundary'][0]
        if n['pixels']==12 and n['color'] in ('W','G'): dm.append({'b':n['color'],'c':(b[0]+2,b[1]),'core':None})
    for n in seg['nodes']:
        if n['pixels']!=1 or n['color'] not in ('O','p'): continue
        r,c=n['boundary'][0]
        for d in dm:
            if abs(d['c'][0]-r)+abs(d['c'][1]-c)<=2: d['core']=n['color']
    w=[d for d in dm if d['b']=='W'][0]; gs=[d for d in dm if d['b']=='G']
    return ((w['c'],w['core']),)+tuple((g['c'],g['core']) for g in gs)
